// This code:
// 1. Searches through all fields in the incoming JSON.
// 2. Finds the values for Name, Email, Start Date, Department, Manager Name, and Manager Email.
// 3. Searches all fields ending with "Role" to find the one role that has a selected value.
// 4. Ignores Role fields where the value is null, empty, or missing.
// 5. Returns the information in the requested order.
// 6. Works even if the question IDs change or the selected Role changes.

// Get the incoming JSON data
const data = $json;

// Function to find a field by its label
const findValueByLabel = (label) => {
  for (const key of Object.keys(data)) {
    const field = data[key];

    if (
      field &&
      typeof field === "object" &&
      field.label === label
    ) {
      return field.value;
    }
  }

  return null;
};

// Find the selected Role dynamically
const findSelectedRole = () => {
  for (const key of Object.keys(data)) {
    const field = data[key];

    if (
      field &&
      typeof field === "object" &&
      field.label &&
      field.label.toLowerCase().endsWith("role") &&
      field.value !== null &&
      field.value !== undefined &&
      String(field.value).trim() !== ""
    ) {
      return field.value;
    }
  }

  return null;
};

// Extract the required information
const name = findValueByLabel("Name");
const email = findValueByLabel("Email");
const startDate = findValueByLabel("Start Date");
const department = findValueByLabel("Department");
const role = findSelectedRole();
const managerName = findValueByLabel("Manager Name");
const managerEmail = findValueByLabel("Manager Email");

// Return the results in the requested order
return [
  {
    json: {
      Name: name,
      Email: email,
      "Start Date": startDate,
      Department: department,
      Role: role,
      "Manager Name": managerName,
      "Manager Email": managerEmail
    }
  }
];

// This code:
// 1. Reads the AI-generated text from the "output" field.
// 2. Adds the current date as "Date Created" in the format "June 30, 2026".
// 3. Separates the main information into individual JSON fields.
// 4. Extracts the title, Role, Department, Start Date, and Reporting To.
// 5. Separates the Welcome Message and Closing Note.
// 6. Separates each Week into its own JSON field.
// 7. Separates each Day within each Week into individual fields.
// 8. Works dynamically even when the onboarding content changes.

// Get the AI output
const text = $json.output || "";

// Get the current date
const today = new Date();

// Format current date as "June 30, 2026"
const formatDate = (date) => {
  return date.toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric"
  });
};

// Create the final result
const result = {
  "Date Created": formatDate(today)
};

// Extract the title
const titleMatch = text.match(/^(.+?)(?=\nRole:)/);

if (titleMatch) {
  result.title = titleMatch[1].trim();
}

// Extract basic employee information
const roleMatch = text.match(/Role:\s*(.+)/);
const departmentMatch = text.match(/Department:\s*(.+)/);
const startDateMatch = text.match(/Start Date:\s*(.+)/);
const reportingToMatch = text.match(/Reporting To:\s*(.+)/);

result.role = roleMatch ? roleMatch[1].trim() : null;
result.department = departmentMatch ? departmentMatch[1].trim() : null;
result.start_date = startDateMatch ? startDateMatch[1].trim() : null;
result.reporting_to = reportingToMatch ? reportingToMatch[1].trim() : null;

// Extract Welcome Message
const welcomeMatch = text.match(
  /Welcome Message:\n([\s\S]*?)(?=\n\nWEEK \d+:|$)/
);

result.welcome_message = welcomeMatch
  ? welcomeMatch[1].trim()
  : null;

// Extract Weeks
const weekRegex = /WEEK (\d+):\s*(.+?)\n([\s\S]*?)(?=\n\nWEEK \d+:|\n\nClosing Note:|$)/g;

let weekMatch;

while ((weekMatch = weekRegex.exec(text)) !== null) {
  const weekNumber = weekMatch[1];
  const weekTitle = weekMatch[2].trim();
  const weekContent = weekMatch[3].trim();

  const days = {};

  // Extract each Day within the Week
  const dayRegex = /Day (\d+):\s*(.+?)\n([\s\S]*?)(?=\n\nDay \d+:|$)/g;

  let dayMatch;

  while ((dayMatch = dayRegex.exec(weekContent)) !== null) {
    const dayNumber = dayMatch[1];
    const dayTitle = dayMatch[2].trim();
    const dayDescription = dayMatch[3].trim();

    days[`Day ${dayNumber}`] = {
      title: dayTitle,
      description: dayDescription
    };
  }

  result[`week_${weekNumber}`] = {
    title: weekTitle,
    days
  };
}

// Extract Closing Note
const closingMatch = text.match(
  /Closing Note:\n([\s\S]*?)$/
);

result.closing_note = closingMatch
  ? closingMatch[1].trim()
  : null;

// Return the cleaned JSON
return [
  {
    json: result
  }
];

